'use client';

import React, { useState, useEffect, useRef } from 'react';
import { JobRequest, WorkerLocation } from '@/types';
import { 
  MapPin, 
  Navigation, 
  Clock, 
  Phone, 
  ShieldCheck, 
  Compass, 
  ExternalLink, 
  Play, 
  Pause, 
  CheckCircle2,
  AlertTriangle,
  Radio,
  Zap,
  Share2,
  Lock,
  Layers,
  Sparkles,
  ChevronRight,
  Bike,
  Volume2,
  HelpCircle,
  Copy,
  Check
} from 'lucide-react';

interface LiveTrackerMapProps {
  job: JobRequest;
  onClose?: () => void;
  workerPhone?: string;
  workerPhoto?: string;
}

// Haversine distance calculator in Kilometers
function calculateDistanceKm(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const R = 6371; // Earth's radius in km
  const dLat = (lat2 - lat1) * (Math.PI / 180);
  const dLon = (lon2 - lon1) * (Math.PI / 180);
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(lat1 * (Math.PI / 180)) *
      Math.cos(lat2 * (Math.PI / 180)) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

export default function LiveTrackerMap({ job, onClose, workerPhone, workerPhoto }: LiveTrackerMapProps) {
  // Coordinates
  const defaultCustomerCoords = { lat: 28.6289, lng: 77.2065 };
  const defaultWorkerCoords: WorkerLocation = {
    lat: 28.6380,
    lng: 77.2240,
    accuracy: 6,
    heading: 215,
    speed: 24.5,
    updated_at: new Date().toISOString(),
    address: 'Connaught Circus, Block B, New Delhi'
  };

  const customerCoords = job.customer_coordinates || defaultCustomerCoords;
  
  // Real-time worker position
  const [workerPos, setWorkerPos] = useState<WorkerLocation>(
    job.worker_location || defaultWorkerCoords
  );

  const [isSimulating, setIsSimulating] = useState(false);
  const [simProgress, setSimProgress] = useState(0.15);
  const [lastPingTime, setLastPingTime] = useState<Date>(new Date());
  const [copiedLink, setCopiedLink] = useState(false);
  const [mapType, setMapType] = useState<'standard' | 'dark' | 'satellite'>('dark');

  // Generate a deterministic 4-digit security start OTP for Amazon/Flipkart style security
  const startOtp = Math.abs((job.id.split('').reduce((acc, c) => acc + c.charCodeAt(0), 0) * 73) % 9000 + 1000);

  // Sync with prop updates
  useEffect(() => {
    if (job.worker_location && !isSimulating) {
      setWorkerPos(job.worker_location);
      setLastPingTime(new Date(job.worker_location.updated_at || Date.now()));
    }
  }, [job.worker_location, isSimulating]);

  // Turn-by-turn road waypoints simulation (Delhi grid)
  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (isSimulating) {
      interval = setInterval(() => {
        setSimProgress(prev => {
          const next = prev + 0.04;
          if (next >= 1) {
            setIsSimulating(false);
            return 1;
          }
          // Road curving simulation with bezier-like intermediate offsets
          const startLat = defaultWorkerCoords.lat;
          const startLng = defaultWorkerCoords.lng;
          const curveOffset = Math.sin(next * Math.PI) * 0.0035;

          const currentLat = startLat + (customerCoords.lat - startLat) * next + curveOffset * 0.5;
          const currentLng = startLng + (customerCoords.lng - startLng) * next + curveOffset;

          const newLoc: WorkerLocation = {
            lat: Number(currentLat.toFixed(6)),
            lng: Number(currentLng.toFixed(6)),
            accuracy: Math.floor(4 + Math.random() * 5),
            heading: 215 + Math.floor(Math.sin(next * 10) * 25),
            speed: Number((22 + Math.random() * 8).toFixed(1)),
            updated_at: new Date().toISOString(),
            address: next > 0.85 
              ? 'Arriving in 150 meters • Turning into customer street' 
              : next > 0.5 
              ? 'On Janpath Road • Moving smoothly' 
              : 'En route via Barakhamba Circle'
          };

          setWorkerPos(newLoc);
          setLastPingTime(new Date());

          return next;
        });
      }, 1200);
    }
    return () => clearInterval(interval);
  }, [isSimulating, customerCoords]);

  // Dynamic Distance & ETA calculations
  const distanceKm = calculateDistanceKm(
    workerPos.lat,
    workerPos.lng,
    customerCoords.lat,
    customerCoords.lng
  );
  
  // ETA assuming ~25 km/h city speed
  const etaMinutes = Math.max(1, Math.round((distanceKm / 24) * 60));
  const estimatedArrivalTime = new Date(Date.now() + etaMinutes * 60000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  // 2D Normalized Projections for Vector Overlay
  const minLat = Math.min(workerPos.lat, customerCoords.lat) - 0.007;
  const maxLat = Math.max(workerPos.lat, customerCoords.lat) + 0.007;
  const minLng = Math.min(workerPos.lng, customerCoords.lng) - 0.007;
  const maxLng = Math.max(workerPos.lng, customerCoords.lng) + 0.007;

  const getSvgX = (lng: number) => ((lng - minLng) / (maxLng - minLng || 1)) * 74 + 13;
  const getSvgY = (lat: number) => (1 - (lat - minLat) / (maxLat - minLat || 1)) * 74 + 13;

  const workerSvgX = getSvgX(workerPos.lng);
  const workerSvgY = getSvgY(workerPos.lat);
  const customerSvgX = getSvgX(customerCoords.lng);
  const customerSvgY = getSvgY(customerCoords.lat);

  const handleShareTracking = () => {
    navigator.clipboard.writeText(window.location.href);
    setCopiedLink(true);
    setTimeout(() => setCopiedLink(false), 2500);
  };

  const googleMapsDirectionsUrl = `https://www.google.com/maps/dir/?api=1&origin=${workerPos.lat},${workerPos.lng}&destination=${customerCoords.lat},${customerCoords.lng}&travelmode=driving`;

  return (
    <div className="flex flex-col h-full w-full bg-slate-950 text-white rounded-3xl overflow-hidden shadow-2xl border border-slate-800 animate-fade-in">
      
      {/* AMAZON / FLIPKART STYLE TOP LIVE TRACKING BAR */}
      <div className="p-4 sm:p-5 bg-slate-900 border-b border-slate-800/90 flex flex-col sm:flex-row sm:items-center justify-between gap-3 shadow-md">
        
        <div className="flex items-center gap-3.5">
          <div className="relative shrink-0">
            <div className="w-13 h-13 rounded-2xl bg-gradient-to-tr from-amber-500 to-amber-600 p-0.5 shadow-lg shadow-amber-500/20">
              <div className="w-full h-full rounded-[14px] bg-slate-900 flex items-center justify-center overflow-hidden">
                {workerPhoto ? (
                  <img src={workerPhoto} alt={job.worker_name} className="w-full h-full object-cover" />
                ) : (
                  <span className="font-black text-amber-400 text-lg">{job.worker_name.charAt(0)}</span>
                )}
              </div>
            </div>
            <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-emerald-500 border-2 border-slate-900 rounded-full flex items-center justify-center" title="Live GPS Connected">
              <span className="w-1.5 h-1.5 bg-white rounded-full animate-ping" />
            </div>
          </div>

          <div>
            <div className="flex items-center gap-2">
              <h3 className="font-extrabold text-base text-white">{job.worker_name}</h3>
              <span className="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-blue-500/20 text-blue-400 border border-blue-500/30 flex items-center gap-1">
                <ShieldCheck className="w-3 h-3 text-blue-400" /> VERIFIED PARTNER
              </span>
            </div>
            <div className="text-xs text-slate-400 flex items-center gap-2 mt-0.5">
              <span>{job.service_name}</span>
              <span>•</span>
              <span className="text-emerald-400 font-semibold flex items-center gap-1">
                <Radio className="w-3 h-3 animate-pulse" /> LIVE TRACKING ACTIVE
              </span>
            </div>
          </div>
        </div>

        {/* Action Controls (Simulate / Open Google Maps / Share) */}
        <div className="flex items-center gap-2 self-end sm:self-center">
          <a
            href={googleMapsDirectionsUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="px-3 py-2 rounded-xl text-xs font-bold bg-white text-slate-900 hover:bg-slate-100 shadow-md transition-all flex items-center gap-1.5"
            title="Open in Google Maps App"
          >
            <ExternalLink className="w-3.5 h-3.5 text-blue-600" /> Google Maps
          </a>

          <button
            onClick={() => {
              if (!isSimulating && simProgress >= 1) setSimProgress(0);
              setIsSimulating(!isSimulating);
            }}
            className={`px-3 py-2 rounded-xl text-xs font-bold border transition-all flex items-center gap-1.5 ${
              isSimulating
                ? 'bg-amber-500/20 border-amber-500/40 text-amber-300'
                : 'bg-slate-800 border-slate-700 text-slate-300 hover:bg-slate-700 hover:text-white'
            }`}
          >
            {isSimulating ? (
              <>
                <Pause className="w-3.5 h-3.5 fill-amber-300" /> Pause Sim
              </>
            ) : (
              <>
                <Play className="w-3.5 h-3.5 fill-slate-300" /> Live Demo
              </>
            )}
          </button>

          <button
            onClick={handleShareTracking}
            className="p-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 hover:text-white border border-slate-700 transition-all"
            title="Share Live Tracking Link"
          >
            {copiedLink ? <Check className="w-4 h-4 text-emerald-400" /> : <Share2 className="w-4 h-4" />}
          </button>
        </div>

      </div>

      {/* FLIPKART / AMAZON STYLE DELIVERY STATUS BANNER */}
      <div className="bg-gradient-to-r from-blue-950 via-slate-900 to-indigo-950 px-5 py-3 border-b border-slate-800 flex flex-col sm:flex-row sm:items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 flex items-center justify-center font-black shrink-0">
            <Bike className="w-5 h-5 animate-bounce" />
          </div>
          <div>
            <div className="text-xs text-slate-400 font-medium">Estimated Arrival at Doorstep</div>
            <div className="text-lg sm:text-xl font-black text-white flex items-center gap-2">
              <span>{estimatedArrivalTime}</span>
              <span className="text-xs font-bold text-emerald-400 bg-emerald-950/80 px-2 py-0.5 rounded-full border border-emerald-500/30">
                ~{etaMinutes} mins ({distanceKm.toFixed(1)} km)
              </span>
            </div>
          </div>
        </div>

        {/* 4-Digit Security Start OTP */}
        <div className="flex items-center gap-3 bg-slate-900/90 border border-slate-700/80 px-3.5 py-1.5 rounded-2xl">
          <div className="text-right">
            <div className="text-[10px] uppercase font-bold text-slate-400 flex items-center gap-1 justify-end">
              <Lock className="w-2.5 h-2.5 text-amber-400" /> Safety Start OTP
            </div>
            <div className="text-base font-black tracking-widest text-amber-400 font-mono">
              {startOtp}
            </div>
          </div>
          <div className="text-[10px] text-slate-400 max-w-[120px] leading-tight border-l border-slate-700 pl-2">
            Share with {job.worker_name.split(' ')[0]} upon arrival
          </div>
        </div>
      </div>

      {/* INTERACTIVE MAP VIEWPORT */}
      <div className="relative flex-1 min-h-[380px] sm:min-h-[440px] bg-slate-950 overflow-hidden select-none">
        
        {/* Google Maps Base Tile Frame */}
        <iframe
          title="Google Map Live Route"
          src={`https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d14008.248548085278!2d${workerPos.lng}!3d${workerPos.lat}!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x390ce2d1134261d9%3A0x6b4db63f6c8d7dfb!2sConnaught%20Place%2C%20New%20Delhi!5e0!3m2!1sen!2sin!4v1700000000000!5m2!1sen!2sin`}
          className={`absolute inset-0 w-full h-full pointer-events-none transition-all duration-500 ${
            mapType === 'dark' 
              ? 'opacity-70 contrast-125 brightness-75 invert-[0.9] hue-rotate-180' 
              : mapType === 'satellite' 
              ? 'opacity-85 contrast-110' 
              : 'opacity-80'
          }`}
          style={{ border: 0 }}
          loading="lazy"
        />

        {/* Dark Grid Overlay & Subtle Radial Light */}
        <div className="absolute inset-0 bg-[radial-gradient(#3b82f618_1.5px,transparent_1.5px)] [background-size:28px_28px] pointer-events-none" />
        <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-transparent to-slate-950/80 pointer-events-none" />

        {/* Vector Route Line & Animated Pulses */}
        <svg className="absolute inset-0 w-full h-full pointer-events-none" preserveAspectRatio="none">
          <defs>
            <linearGradient id="amazonRouteGradient" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stopColor="#10b981" />
              <stop offset="50%" stopColor="#3b82f6" />
              <stop offset="100%" stopColor="#6366f1" />
            </linearGradient>
            <filter id="routeGlow" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="4" result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
          </defs>

          {/* Glowing Breadcrumb Route Path */}
          <line
            x1={`${workerSvgX}%`}
            y1={`${workerSvgY}%`}
            x2={`${customerSvgX}%`}
            y2={`${customerSvgY}%`}
            stroke="url(#amazonRouteGradient)"
            strokeWidth="5"
            strokeDasharray="10 6"
            className="animate-[dash_1.2s_linear_infinite]"
            filter="url(#routeGlow)"
          />
        </svg>

        {/* Destination Pin (Customer House) */}
        <div 
          className="absolute flex flex-col items-center -translate-x-1/2 -translate-y-1/2 transition-all duration-700 z-10"
          style={{ left: `${customerSvgX}%`, top: `${customerSvgY}%` }}
        >
          <div className="relative">
            <div className="w-11 h-11 rounded-2xl bg-indigo-600 border-2 border-white text-white shadow-2xl shadow-indigo-500/50 flex items-center justify-center">
              <MapPin className="w-6 h-6 text-white fill-white/20" />
            </div>
            <div className="absolute -inset-3 bg-indigo-500/30 rounded-full animate-ping -z-10" />
          </div>
          <div className="mt-1.5 px-3 py-1 rounded-xl bg-slate-900/95 border border-indigo-500/50 text-[11px] font-bold text-indigo-300 shadow-xl whitespace-nowrap">
            🏠 Your Service Location
          </div>
        </div>

        {/* Live Moving Partner Marker (Uber / Flipkart Style Delivery Pin) */}
        <div 
          className="absolute flex flex-col items-center -translate-x-1/2 -translate-y-1/2 transition-all duration-1000 ease-out z-20"
          style={{ left: `${workerSvgX}%`, top: `${workerSvgY}%` }}
        >
          <div className="relative">
            {/* Live GPS Radar Waves */}
            <div className="absolute -inset-5 bg-emerald-500/30 rounded-full animate-ping" />
            
            {/* Moving Vehicle / Technician Pin */}
            <div className="w-13 h-13 rounded-2xl bg-gradient-to-tr from-emerald-400 to-teal-500 p-0.5 shadow-2xl shadow-emerald-500/60">
              <div className="w-full h-full rounded-[14px] bg-slate-900 flex items-center justify-center overflow-hidden relative">
                {workerPhoto ? (
                  <img src={workerPhoto} alt={job.worker_name} className="w-full h-full object-cover" />
                ) : (
                  <Navigation className="w-6 h-6 text-emerald-400 rotate-45" />
                )}
                <div className="absolute bottom-0 inset-x-0 h-1.5 bg-emerald-400" />
              </div>
            </div>

            {/* Direction Heading Pointer */}
            <div 
              className="absolute -top-2.5 left-1/2 -translate-x-1/2 w-0 h-0 border-l-[7px] border-l-transparent border-r-[7px] border-r-transparent border-b-[9px] border-b-emerald-400 shadow-sm"
              style={{ transform: `translateX(-50%) rotate(${workerPos.heading || 0}deg)` }}
            />
          </div>

          <div className="mt-2 px-3.5 py-1.5 rounded-2xl bg-slate-900/95 border border-emerald-500/50 shadow-2xl text-center whitespace-nowrap">
            <div className="text-xs font-black text-emerald-400 flex items-center gap-1.5 justify-center">
              <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
              {job.worker_name}
            </div>
            <div className="text-[10px] text-slate-400 font-semibold mt-0.5">
              {workerPos.speed ? `${workerPos.speed} km/h` : 'Moving'} • ±{workerPos.accuracy || 6}m GPS
            </div>
          </div>
        </div>

        {/* Live GPS Ping Badge */}
        <div className="absolute bottom-4 left-4 z-30">
          <div className="px-3.5 py-1.5 rounded-xl bg-slate-900/90 backdrop-blur-md border border-slate-800 text-[10px] text-slate-300 flex items-center gap-2 shadow-lg">
            <span className="w-2 h-2 rounded-full bg-emerald-500 animate-ping" />
            <span>Last GPS Heartbeat: {lastPingTime.toLocaleTimeString()}</span>
          </div>
        </div>

        {/* Live Street Address Pill */}
        <div className="absolute top-4 right-4 z-30 max-w-xs hidden sm:block">
          <div className="px-3.5 py-2 rounded-2xl bg-slate-900/90 backdrop-blur-md border border-slate-800 text-xs text-slate-300 shadow-xl flex items-center gap-2">
            <Compass className="w-4 h-4 text-blue-400 shrink-0" />
            <span className="truncate">{workerPos.address || 'Central Transit Route'}</span>
          </div>
        </div>
      </div>

      {/* FLIPKART / AMAZON PROGRESS TIMELINE & DETAILS */}
      <div className="p-5 sm:p-6 bg-slate-900 border-t border-slate-800 space-y-4">
        
        {/* Step-by-Step Progress Pipeline */}
        <div className="grid grid-cols-4 gap-2 py-1">
          
          <div className="p-2.5 rounded-2xl border text-center transition-all bg-emerald-500/10 border-emerald-500/30 text-emerald-400">
            <div className="text-[10px] font-bold text-slate-400 uppercase">Step 1</div>
            <div className="text-xs font-extrabold mt-0.5 flex items-center justify-center gap-1">
              <Check className="w-3 h-3 text-emerald-400" /> Booked
            </div>
          </div>

          <div className="p-2.5 rounded-2xl border text-center transition-all bg-emerald-500/10 border-emerald-500/30 text-emerald-400">
            <div className="text-[10px] font-bold text-slate-400 uppercase">Step 2</div>
            <div className="text-xs font-extrabold mt-0.5 flex items-center justify-center gap-1">
              <Check className="w-3 h-3 text-emerald-400" /> Assigned
            </div>
          </div>

          <div className={`p-2.5 rounded-2xl border text-center transition-all ${
            ['ON_THE_WAY', 'STARTED', 'COMPLETED'].includes(job.status)
              ? 'bg-blue-500/20 border-blue-500/50 text-blue-300 font-bold shadow-lg shadow-blue-500/10'
              : 'bg-slate-800/40 border-slate-800 text-slate-500'
          }`}>
            <div className="text-[10px] font-bold uppercase">Step 3</div>
            <div className="text-xs font-extrabold mt-0.5 flex items-center justify-center gap-1">
              On The Way
            </div>
          </div>

          <div className={`p-2.5 rounded-2xl border text-center transition-all ${
            ['STARTED', 'COMPLETED'].includes(job.status)
              ? 'bg-emerald-500/20 border-emerald-500/50 text-emerald-300 font-bold'
              : 'bg-slate-800/40 border-slate-800 text-slate-500'
          }`}>
            <div className="text-[10px] font-bold uppercase">Step 4</div>
            <div className="text-xs font-extrabold mt-0.5">At Doorstep</div>
          </div>

        </div>

        {/* Customer Location & Service Info */}
        <div className="p-4 rounded-2xl bg-slate-950 border border-slate-800/90 text-xs text-slate-300 flex flex-col sm:flex-row sm:items-center justify-between gap-3">
          <div>
            <span className="text-slate-500 font-semibold uppercase text-[10px]">Service Destination:</span>
            <div className="font-bold text-white text-sm mt-0.5 flex items-center gap-1.5">
              <MapPin className="w-4 h-4 text-red-500 shrink-0" />
              <span>{job.location}</span>
            </div>
          </div>
          <div className="text-right sm:shrink-0">
            <span className="text-slate-500 font-semibold uppercase text-[10px]">Total Fixed Fee:</span>
            <div className="font-black text-emerald-400 text-base">₹{job.fee}</div>
          </div>
        </div>

        {/* Quick Action Buttons (Call / Close) */}
        <div className="flex items-center gap-3 pt-1">
          {workerPhone && (
            <a
              href={`tel:${workerPhone}`}
              className="flex-1 py-3 px-4 rounded-2xl bg-blue-600 hover:bg-blue-500 text-white font-bold text-xs shadow-lg shadow-blue-600/30 flex items-center justify-center gap-2 transition-all hover-lift"
            >
              <Phone className="w-4 h-4" /> Call {job.worker_name} ({workerPhone})
            </a>
          )}
          {onClose && (
            <button
              onClick={onClose}
              className="px-6 py-3 rounded-2xl bg-slate-800 hover:bg-slate-700 text-slate-300 hover:text-white font-bold text-xs border border-slate-700 transition-all"
            >
              Close Live Tracker
            </button>
          )}
        </div>

      </div>

    </div>
  );
}
